package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="mensajes_internos")
public class MensajeInterno{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="min_id")private Long id;@Column(name="cin_id",nullable=false)private Long conversacionId;@Column(name="usu_id_rem",nullable=false)private Long remitenteId;@Column(name="min_con",nullable=false,length=4000)private String contenido;@Column(name="min_cla",nullable=false,length=10)private String clasificacion="NORMAL";@Column(name="min_fec",nullable=false)private LocalDateTime fecha;@Column(name="min_fec_mod")private LocalDateTime fechaModificacion;@Column(name="min_act",nullable=false)private Boolean activo=true;public Long getId(){return id;}public Long getConversacionId(){return conversacionId;}public void setConversacionId(Long v){conversacionId=v;}public Long getRemitenteId(){return remitenteId;}public void setRemitenteId(Long v){remitenteId=v;}public String getContenido(){return contenido;}public void setContenido(String v){contenido=v;}public String getClasificacion(){return clasificacion;}public void setClasificacion(String v){clasificacion=v;}public LocalDateTime getFecha(){return fecha;}public void setFecha(LocalDateTime v){fecha=v;}public LocalDateTime getFechaModificacion(){return fechaModificacion;}public void setFechaModificacion(LocalDateTime v){fechaModificacion=v;}public Boolean getActivo(){return activo;}public void setActivo(Boolean v){activo=v;}}
